import java.util.*;import java.lang.reflect.*;import android.app.*;import android.view.*;import android.widget.*;import android.content.*;import androidx.fragment.app.*;import com.nice.room.ui.RoomLiveActivity;import com.nice.room.ui.roomlive.fragment.ask.answer.*;import com.nice.room.ui.roomlive.fragment.ask.result.*;import com.hailiang.common.util.AppRuntimeData;import com.hailiang.handwrite.bean.*;import com.hailiang.handwrite.widget.*;import com.hljzjx.classroom.mod.*;
public class ToolsTest{
static int checks;static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}static FrameLayout.LayoutParams full(){return new FrameLayout.LayoutParams(-1,-1,0);}static TextView named(View v,String text){if(v instanceof TextView && text.equals(((TextView)v).text))return (TextView)v;if(v instanceof ViewGroup)for(View child:((ViewGroup)v).children){TextView x=named(child,text);if(x!=null)return x;}return null;}static TextView visible(View v,String text){if(v.visibility!=View.VISIBLE)return null;if(v instanceof TextView && text.equals(((TextView)v).text))return (TextView)v;if(v instanceof ViewGroup)for(View child:((ViewGroup)v).children){TextView x=visible(child,text);if(x!=null)return x;}return null;}
static class Page{RoomLiveActivity a=new RoomLiveActivity();FrameLayout host=new FrameLayout(a),root=new FrameLayout(a);TextView submit=new TextView(a);Page(){host.id=200;host.clickable=true;host.focusable=true;host.attach();host.addView(root,full());submit.id=500;root.addView(submit,full());QuestionPptReturn.install(root);}}
static void tap(View v){while(v.click==null && v.parent!=null)v=v.parent;v.performClick();}
static void continuations(){for(int kind=0;kind<5;kind++){
Page p=new Page();QuestionAskAnswerBaseFragment f=kind==3?new QuestionAskHandwriteFragment():new QuestionAskAnswerBaseFragment();f.root=p.root;f.ask=100+kind;f.values.add("original");
QuestionActions.install(f,p.root);View.drain();FragmentTransaction before=new FragmentTransaction();HandwriteContinuation.removeOrKeep(before,f);ok(before.removed.size()==1,"active answers are still removed normally");ok(!HandwriteContinuation.consumeSubmit(f),"active submission falls through unchanged");
f.submitted=true;f.finished=true;FragmentTransaction tx=new FragmentTransaction();HandwriteContinuation.removeOrKeep(tx,f);ok(tx.removed.isEmpty(),"ended answer retained for every type");ok(p.root.visibility==View.INVISIBLE,"result initially hides draft");ok("保存本地练习".equals(p.submit.text) && p.submit.enabled,"local save control replaces old submit");
FrameLayout result=new FrameLayout(p.a);p.host.addView(result,full());QuestionAskAnswerResultBaseFragment r=new QuestionAskAnswerResultBaseFragment();r.root=result;r.ask=f.ask;QuestionActions.install(r,result);HandwriteContinuation.attachResult(r,result);QuestionPptReturn.setResumeLabel(result,"答题结果");View.drain();
TextView resume=visible(p.host,"继续作答");ok(resume!=null,"all result types offer continue answer");resume.performClick();ok(p.root.visibility==View.VISIBLE && result.visibility==View.INVISIBLE,"switch back to original input instance");ok(named(p.root,kind==3?"上传续答":"保存本地练习")!=null,"original input data and continuation controls retained");
f.values.add("local-change");ok(HandwriteContinuation.saveDraft(f),"ended changes go to separate local store");ok(HandwriteContinuation.consumeSubmit(f),"ended save cannot trigger first-submit network path");ok(f.submitted && f.finished && "original".equals(f.submittedAnswer),"server completion and original answer unchanged");
String store=kind==3?"mod_handwrite_continuations":"mod_question_continuations";ok(Context.preferences.get(store).data.containsKey("17_2_"+f.ask),"private user/room/question key");
if(kind!=3){f.broken=true;HandwriteContinuation.consumeSubmit(f);ok(Toast.messages.get(Toast.messages.size()-1).contains("失败"),"failed persistence does not claim saved");f.broken=false;}
AppRuntimeData.user=99;ok(!HandwriteContinuation.saveDraft(f),"new login cannot receive previous user draft");AppRuntimeData.user=17;
TextView back=visible(p.host,"返回 PPT");back.performClick();ok(p.root.visibility==View.INVISIBLE && !p.host.clickable,"PPT still accessible during local practice");TextView again=visible(p.host,"继续作答");again.performClick();ok(p.root.visibility==View.VISIBLE,"local answer restores after PPT");
resume.performClick();ok(result.visibility==View.VISIBLE,"original result remains accessible");resume.performClick();p.host.removeView(result);
FrameLayout refreshed=new FrameLayout(p.a);p.host.addView(refreshed,full());QuestionAskAnswerResultBaseFragment r2=new QuestionAskAnswerResultBaseFragment();r2.root=refreshed;r2.ask=f.ask;QuestionActions.install(r2,refreshed);HandwriteContinuation.attachResult(r2,refreshed);QuestionPptReturn.setResumeLabel(refreshed,"答题结果");View.drain();ok(refreshed.visibility==View.INVISIBLE && p.root.visibility==View.VISIBLE,"native init ordering defers suspend until controls exist");visible(p.host,"答题结果").performClick();ok(refreshed.visibility==View.VISIBLE && p.root.visibility==View.INVISIBLE,"refreshed result and original practice remain paired");
p.host.removeView(p.root);p.host.removeView(refreshed);View.drain();ok(p.root.tree.listeners.isEmpty() && result.tree.listeners.isEmpty() && refreshed.tree.listeners.isEmpty(),"question action observers removed with views");ok(p.host.clickable && p.host.focusable,"all shared touch gates released");
}}
static void aiAndMedia()throws Exception{
Page p=new Page();QuestionAskHandwriteFragment f=new QuestionAskHandwriteFragment();f.root=p.root;f.canvas=new HandwriteView(p.a);QuestionActions.install(f,p.root);View.drain();
named(p.host,"AI 问问").performClick();ok(named(Dialog.last.content,"海亮自带")!=null && named(Dialog.last.content,"ChatGPT")!=null,"question AI uses existing two choices");tap(named(Dialog.last.content,"海亮自带"));ok(p.a.actions.equals(Arrays.asList(0)),"official choice uses original AI bridge");
named(p.host,"AI 问问").performClick();tap(named(Dialog.last.content,"ChatGPT"));ok(android.webkit.WebView.created.get(android.webkit.WebView.created.size()-1).url().equals("https://chatgpt.com/"),"ChatGPT stays in existing in-app browser");ChatWebPanel.close(p.a);
named(p.host,"拍照／相册").performClick();named(Dialog.last.content,"从相册导入").performClick();ok(f.lastRequest==0x6a32 && "image/*".equals(f.lastIntent.type) && !f.lastIntent.multiple,"handwriting offers single-image system picker");QuestionMedia.result(f,0x6a32,0,null);
QuestionMedia.open(f);named(Dialog.last.content,"拍照").performClick();ok(com.nice.room.ui.roomlive.fragment.ask.TakePhotoFragment.last!=null,"camera uses existing shared camera/album fragment");
// Execute actual private insertion code; final DEX checks separately establish
// that the original native serializer and first submission are preserved.
int[] pixels={0xff000000,0xff000000,0xffffffff,0xffffffff,0xff000000,0xffffffff};InkPhotoPlan plan=InkPhotoPlan.convert(pixels,3,2,100,100,false);
PathInfo old=new PathInfo();old.pathID=12;old.pointsList=new ArrayList<>();f.canvas.record.paths.add(old);DrawingRecord previous=f.canvas.record;
Class<?> state=Class.forName("com.hljzjx.classroom.mod.QuestionMedia$State");Constructor<?> ctor=state.getDeclaredConstructors()[0];ctor.setAccessible(true);Object s=ctor.newInstance(f);
Method insert=QuestionMedia.class.getDeclaredMethod("insert",state,InkPhotoPlan.class);insert.setAccessible(true);insert.invoke(null,s,plan);
ok(f.canvas.record!=previous && f.canvas.record.paths.size()==plan.runs.size()+1,"photo converted into native stroke record");ok(f.canvas.record.paths.get(plan.runs.size())==old,"existing handwritten paths stay above photo");
HashSet<Long> ids=new HashSet<>();for(int i=0;i<plan.runs.size();i++){PathInfo path=f.canvas.record.paths.get(i);ok(path.drawType==1 && path.alpha==1 && path.strokeWidth>0 && path.pointsList.size()==2,"ordinary supported LINE path");ok(ids.add(path.pathID),"unique path IDs");for(PointInfo point:path.pointsList)ok(point.phoneWidth==1280 && point.phoneHeight==800 && point.x>=0 && point.x<=1280 && point.y>=0 && point.y<=800,"same native source coordinate frame");}
DrawingRecord accepted=f.canvas.record;com.hailiang.handwrite.serialize.XYStrokeSerializer.oversized=true;insert.invoke(null,s,plan);ok(f.canvas.record==accepted,"oversized payload rejected before changing original record");com.hailiang.handwrite.serialize.XYStrokeSerializer.oversized=false;
QuestionPptReturn.suspend(p.root);ok(named(p.host,"AI 问问").getParent()!=null,"AI remains same-container action");LinearLayout bar=(LinearLayout)named(p.host,"AI 问问").getParent();ok(bar.visibility==View.GONE,"AI/media hide while question is minimized");QuestionPptReturn.resume(p.root);ok(bar.visibility==View.VISIBLE,"AI/media return with the same question");QuestionMedia.destroy(f);p.host.removeView(p.root);View.drain();
}
static void plans(){Random random=new Random(8);for(int test=0;test<160;test++){int w=1+random.nextInt(160),h=1+random.nextInt(160);int[] src=new int[w*h];for(int i=0;i<src.length;i++)src[i]=random.nextBoolean()?0xffffffff:random.nextInt()|0xff000000;
for(boolean color:new boolean[]{false,true}){InkPhotoPlan plan=InkPhotoPlan.convert(src,w,h,130,130,color);ok(plan.runs.size()<=InkPhotoPlan.MAX_RUNS,"conversion bounded by run budget");ok(plan.width>0 && plan.height>0 && plan.width<=130 && plan.height<=130,"bounded dimensions");int[] restored=new int[plan.width*plan.height];Arrays.fill(restored,0xffffffff);for(InkPhotoPlan.Run r:plan.runs){ok(r.start>=0 && r.end<=plan.width && r.end>r.start && r.row<plan.height,"valid nonempty native row range");for(int x=r.start;x<r.end;x++)restored[r.row*plan.width+x]=r.color;}ok(Arrays.equals(restored,plan.pixels),"preview exactly reconstructs encoded run colors");float[] box=InkPhotoPlan.placement(1280,800,plan.width,plan.height);ok(box[0]>=0 && box[1]>=0 && box[0]+plan.width*box[2]<=1281 && box[1]+plan.height*box[2]<=801,"uniform image placement within canvas");}}
int[] white=new int[100];Arrays.fill(white,-1);ok(InkPhotoPlan.convert(white,10,10,10,10,false).runs.isEmpty(),"empty white page adds no hidden payload");}
public static void main(String[] ignored)throws Exception{continuations();aiAndMedia();plans();System.out.println("PASS "+checks+" actual Java question, continuation and photo-conversion assertions");}
}
